#!/usr/bin/env bash\nset -u\nset -o pipefail\nexport PAGER=cat\nexport SYSTEMD_PAGER=cat\ncd "$(git rev-parse --show-toplevel)"\nclear\nsection() { printf "\n\n=== %s ===\n" "$1"; sleep "$2"; }\nrun_cmd() { printf "\n$ %s\n" "$1"; sleep 1; eval "$1"; sleep "$2"; }\nsection "Lab Rescue Agent v0.5 Maximum Polish Demo" 3\nprintf "%s\n" "Seven-agent AI system for multi-scenario certification lab recovery."\nprintf "%s\n" "Safe recovery plans. Readiness insights. Foundry-ready status. Safety-verified reports."\nsleep 5\nsection "Judge quick path from README" 2\nsed -n "1,42p" README.md\nsleep 8\nsection "Available synthetic scenarios" 2\nPYTHONPATH="$PWD/src" python3 -m lab_rescue_agent scenarios\nsleep 7\nsection "Quality gate: evaluation harness" 2\nPYTHONPATH="$PWD/src" python3 -m lab_rescue_agent evaluate | sed -n "1,34p"\nsleep 9\nsection "Foundry readiness status" 2\nPYTHONPATH="$PWD/src" python3 -m lab_rescue_agent foundry-status\nsleep 8\nsection "Export scenario artifacts" 2\nPYTHONPATH="$PWD/src" python3 -m lab_rescue_agent export az204-functions-storage-error\nsleep 6\nsection "Generated judge artifacts" 2\nls -1 demo/output/az204-functions-storage-error_* | sed -n "1,20p"\nsleep 6\nsection "Manager executive brief preview" 2\nsed -n "1,70p" demo/output/az204-functions-storage-error_manager_brief.md\nsleep 10\nsection "Agent trace ledger preview" 2\npython3 -m json.tool demo/output/az204-functions-storage-error_trace.json | sed -n "1,80p"\nsleep 10\nsection "Final smoke test" 2\nPYTHONPATH="$PWD/src" python3 tests/test_demo_workflow.py\nsleep 5\nsection "Demo complete" 2\nprintf "%s\n" "Lab Rescue Agent completed with EVAL_PASS, DEMO_WORKFLOW_SMOKE_OK, and safety-verified outputs."\nsleep 3\n